let current=0;const q=s=>document.querySelector(s),body=q('#stageBody'),title=q('#stageTitle'),kicker=q('#stageKicker'),status=q('#stageStatus'),next=q('#nextBtn'),toast=q('#toast');
function forkNode(on){const n=q('#bobNode');n.classList.toggle('locked',!on);n.querySelector('em').textContent=on?'v0.1':'draft';n.querySelector('strong').textContent=on?(current===4?'pending':'+1.1%'):'—';n.querySelector('small').textContent=on?'Bob · portfolio fork':"Awaiting Bob's fork"}
function render(){const x=stages[current];body.innerHTML=x.b;title.textContent=x.t;kicker.textContent=x.k;status.textContent=x.s;next.innerHTML=x.n+' <span>→</span>';next.disabled=current===stages.length-1;document.querySelectorAll('#steps li').forEach((e,i)=>{e.classList.toggle('active',i===current);e.classList.toggle('done',i<current)});forkNode(current>=4)}
function notify(m){toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
next.addEventListener('click',()=>{if(current<stages.length-1){current++;render();notify(['','Confidential receipt created','Scoped payment authorized','Capability issued to bob.near','Fork published · policy passed','Access revoked · lineage retained'][current])}});
q('#resetBtn').addEventListener('click',()=>{current=0;render();notify('Demo reset')});document.querySelectorAll('#steps li').forEach((e,i)=>e.addEventListener('click',()=>{current=i;render()}));render();
